# -*- coding: utf-8 -*-
"""Artículo 2 (por qué comer kasher) + saludo + colección de historias breves jasídicas."""

BLOQUES = []

BLOQUES.append({"t": "titulo",
  "he": "לָמָּה צָרִיךְ לֶאֱכוֹל כָּשֵׁר?",
  "es": "¿Por qué hay que comer kasher?"})

BLOQUES.append({"t": "par",
  "he": "בְּפָרָשַׁת הַשָּׁבוּעַ, פָּרָשַׁת שְׁמִינִי, מְפָרֶטֶת הַתּוֹרָה אֶת הָעוֹפוֹת הַטְּמֵאִים - הָאֲסוּרִים בַּאֲכִילָה. כֹּה נֶאֱמַר בְּפֶרֶק י\"א:",
  "es": "En la <i>parashá</i> de esta semana, <i>Parashat Shminí</i>, la Torá detalla las aves impuras, prohibidas para comer. Así está dicho en el capítulo 11:"})

BLOQUES.append({"t": "par",
  "he": "\"וְאֶת אֵלֶּה תְּשַׁקְּצוּ מִן הָעוֹף לֹא יֵאָכְלוּ שֶׁקֶץ הֵם: אֶת הַנֶּשֶׁר וְאֶת הַפֶּרֶס וְאֵת הָעָזְנִיָּה. וְאֶת הַדָּאָה וְאֶת הָאַיָּה לְמִינָהּ. אֵת כָּל עֹרֵב לְמִינוֹ. וְאֵת בַּת הַיַּעֲנָה וְאֶת הַתַּחְמָס וְאֶת הַשָּׁחַף; וְאֶת הַנֵּץ לְמִינֵהוּ. וְאֶת הַכּוֹס וְאֶת הַשָּׁלָךְ וְאֶת הַיַּנְשׁוּף. וְאֶת הַתִּנְשֶׁמֶת וְאֶת הַקָּאָת וְאֶת הָרָחָם. וְאֵת הַחֲסִידָה, הָאֲנָפָה לְמִינָהּ; וְאֶת הַדּוּכִיפַת, וְאֶת הָעֲטַלֵּף\".",
  "es": "«Y a estas abominaréis de las aves, no se comerán, son cosa detestable: el águila, el quebrantahuesos y el azor; el milano y el gavilán según su especie; todo cuervo según su especie; el avestruz, la lechuza, la gaviota y el halcón según su especie; el búho, el somormujo y el ibis; el calamón, el pelícano y el buitre; la cigüeña, la garza según su especie, la abubilla y el murciélago» (Vaikrá 11:13-19)."})

BLOQUES.append({"t": "par",
  "he": "הַתּוֹרָה לֹא מְפָרֶטֶת אֶת סִימָנֵי הַטָּהֳרָה בָּעוֹפוֹת, אֶלָּא מְצַיֶּינֶת אֶת שְׁמוֹת הָעוֹפוֹת הַטְּמֵאִים. מִמֵּילָא, כָּל שְׁאָר הָעוֹפוֹת שֶׁאֵינָם מְפוֹרָטִים בְּפָסוּקֵי הַתּוֹרָה - הִינָם טְהוֹרִים וּמוּתָּרִים בַּאֲכִילָה. כָּךְ מוּבָא בְּסֵפֶר הַחִינּוּךְ (מִצְוָה קנז): \"סִימָנֵי הָעוֹף לֹא נֶאֶמְרוּ, לְפִי שֶׁהַתּוֹרָה פֵּירְשָׁה לָנוּ בְּשֵׁם כָּל הַטְּמֵאִים שֶׁבָּעוֹלָם, וְכֵיוָן שֶׁכֵּן הוּא אֵין צוֹרֶךְ לִכְתוֹב לָנוּ סִימָנֵיהֶן, כִּי כָּל עוֹף הַנִּמְצָא בָּעוֹלָם חוּץ מֵהֶם הוּא כָּשֵׁר. וּמִכָּל מָקוֹם, מִפְּנֵי שֶׁכָּל אוֹתָן מִינִין שֶׁהוֹדִיעַתְנוּ הַתּוֹרָה אֵין כָּל אָדָם בָּקִי בָּהֶן, הוֹדִיעוּנוּ חֲכָמִים סִימָנִין בָּהֶן, כְּדֵי שֶׁיַּכִּיר אוֹתָן כָּל אָדָם וְיוּכַל לֶאֱכוֹל מִן הָעוֹפוֹת אַף עַל פִּי שֶׁאֵינוֹ מַכִּיר אֲפִילּוּ אֶחָד מִכָּל הַמִּינִין הַטְּמֵאִים הַמְּפֹרָשִׁים בַּכָּתוּב\".",
  "es": "La Torá no detalla las señales de pureza de las aves, sino que enumera los nombres de las aves impuras. Por lo tanto, todas las demás aves que no están detalladas en los versículos de la Torá son puras y están permitidas para comer. Así se trae en el Séfer HaJinuj (mitzvá 157): «Las señales del ave no se dijeron, porque la Torá nos explicó por nombre a todas las impuras del mundo, y siendo así no hace falta escribirnos sus señales, porque toda ave que se encuentre en el mundo aparte de ellas es <i>kasher</i>. Y de todos modos, porque no toda persona es experta en identificar esas especies que nos dio a conocer la Torá, nos dieron a conocer los sabios señales en ellas, para que cualquier persona las reconozca y pueda comer de las aves aunque no reconozca ni siquiera una de todas las especies impuras explicadas en el texto»."})

BLOQUES.append({"t": "par",
  "he": "הָרַמְבַּ\"ן מְבָאֵר כִּי כָּל הָעוֹפוֹת אוֹתָם אוֹסֶרֶת הַתּוֹרָה לֶאֱכוֹל הִינָם עוֹפוֹת טוֹרְפִים וְדוֹרְסִים. כֹּה דְּבָרָיו: \"הַסִּימָן הַגָּדוֹל בָּעוֹפוֹת הִיא הַדְּרִיסָה, שֶׁכָּל עוֹף הַדּוֹרֵס לְעוֹלָם טָמֵא, כִּי הַתּוֹרָה הִרְחִיקַתְהוּ מִפְּנֵי שֶׁדָּמוֹ מְחוּמָּם לְאַכְזָרִיּוּתוֹ... וְנוֹתֵן אַכְזָרִיּוּת בַּלֵּב\".",
  "es": "El Ramban explica que todas las aves que la Torá prohíbe comer son aves de presa y rapaces. Estas son sus palabras: «La gran señal en las aves es la rapiña, pues toda ave que caza es siempre impura, porque la Torá la alejó porque su sangre está caliente por su crueldad... y transmite crueldad al corazón»."})

BLOQUES.append({"t": "par",
  "he": "קוֹבֵעַ הָרַמְבַּ\"ן: \"וְהִנֵּה כָּל עוֹף שֶׁיִּדְרוֹס נֵדַע שֶׁהוּא מֵאֵלּוּ הַנִּזְכָּרִים, וְאִם בְּיָדוּעַ שֶׁאֵינוֹ דּוֹרֵס - וַדַּאי מוּתָּר\". מַדּוּעַ אָסְרָה הַתּוֹרָה לֶאֱכוֹל עוֹפוֹת טוֹרְפִים? מְבָאֵר הָרַמְבַּ\"ן: \"וְהִנֵּה טַעַם הָאִיסּוּר בָּעוֹפוֹת, מִפְּנֵי אַכְזָרִיּוּת תּוֹלְדוֹתָם, וְהַבְּהֵמוֹת יִיתָּכֵן שֶׁיִּהְיוּ כֵּן, מִפְּנֵי שֶׁאֵין בְּבַעֲלֵי הַגֵּרָה וְהַפַּרְסָה הַשְּׁסוּעָה דּוֹרֵס, וְהַשְּׁאָר כּוּלָּם יִטְרוֹפוּ\". רַבֵּנוּ בְּחַיֵּי מוֹסִיף עַל דִּבְרֵי הָרַמְבַּ\"ן, כִּי כְּשֵׁם שֶׁבּוֹרֵא עוֹלָם אָסַר אֶת הַקְרָבַת הַקָּרְבָּן מֵעוֹפוֹת טְמֵאִים - כָּךְ אָסַר עַל עַמּוֹ, בָּנָיו אֲהוּבָיו, לְאוֹכְלָם.",
  "es": "El Ramban establece: «Y he aquí que toda ave que cace sabremos que es de las mencionadas, y si se sabe con certeza que no caza, ciertamente está permitida». ¿Por qué prohibió la Torá comer aves de presa? Explica el Ramban: «Y he aquí que la razón de la prohibición en las aves es por la crueldad de su naturaleza; y en los animales [terrestres] es posible que sea así también, porque entre los que rumian y tienen la pezuña hendida no hay depredadores, y todos los demás sí cazan». Rabenu Bejaié añade a las palabras del Ramban que, así como el Creador del mundo prohibió ofrecer el sacrificio de aves impuras, así prohibió a Su pueblo, Sus hijos amados, comerlas."})

BLOQUES.append({"t": "par",
  "he": "כֹּה דְּבָרָיו: \"וְהִנֵּה יֵשׁ לָתֵת טַעַם בְּאִיסּוּר הָעוֹפוֹת, כִּי לְפִי שֶׁהקב\"ה בּוֹחֵר הַטּוֹב וְאוֹהֵב הַשִּׁפְלוּת וְכָל שְׁאָר הַמִּידּוֹת הַטּוֹבוֹת, וְשׂוֹנֵא הָאַכְזָרִיּוּת וְכָל שְׁאָר הַמִּידּוֹת הָרָעוֹת. לָכֵן בָּחַר בְּקָרְבָּנוֹ בַּבְּרִיּוֹת הַשְּׁפָלוֹת וְהַתְּמוֹת, וּמֵאוֹתָן שֶׁהוּא יִתְעַלֶּה בָּחַר בָּהֶן לְקָרְבָּן - צִיווָּה אֶת יִשְׂרָאֵל שֶׁיִּהְיֶה מַאֲכָלָם מֵהֶן, וּכְשֵׁם שֶׁהוּא יִתְבָּרַךְ מַרְחִיק הָעוֹפוֹת הַטְּמֵאִים לְצוֹרֶךְ קָרְבָּן, כֵּן מַרְחִיק אוֹתָם לְצוֹרֶךְ מַאֲכָלָם שֶׁל יִשְׂרָאֵל, וְכָל זֶה לְלַמְּדֵנוּ שֶׁהוּא יִתְעַלֶּה שׂוֹנֵא מִידַּת הָרַע וְהָאַכְזָרִיּוּת, וְאוֹהֵב מִידַּת הַטּוֹב וְהַשִּׁפְלוּת וְהַתְּמוֹת\". כְּלוֹמַר, הָעוֹפוֹת הָאֲסוּרִים בַּאֲכִילָה הִינָם אַכְזָרִיִּים, וְכַאֲשֶׁר אוֹכְלִים מֵהֶם - נִכְנֶסֶת מִידַּת הָאַכְזָרִיּוּת בְּגוּפוֹ שֶׁל הָאוֹכֵל. מִשּׁוּם כָּךְ צִיווָּה עָלֵינוּ ה' יִתְבָּרַךְ לֹא לֶאֱכוֹל עוֹפוֹת טְמֵאִים, כְּדֵי שֶׁלֹּא תִּיכָּנֵס בְּדָמֵנוּ מִידַּת הָאַכְזָרִיּוּת. בְּאִיסּוּר זֶה מְלַמְּדֵנוּ בּוֹרֵא עוֹלָם כִּי \"הוּא יִתְעַלֶּה שׂוֹנֵא מִידַּת הָרַע וְהָאַכְזָרִיּוּת, וְאוֹהֵב מִידַּת הַטּוֹב וְהַשִּׁפְלוּת וְהַתְּמוֹת\".",
  "es": "Estas son sus palabras: «Y he aquí que hay que dar una razón para la prohibición de las aves, porque, dado que el Santo, bendito sea, elige lo bueno y ama la humildad y todas las demás buenas cualidades, y odia la crueldad y todas las demás malas cualidades, por eso eligió para Su sacrificio a las criaturas humildes y mansas; y de aquellas [aves] que Él, exaltado sea, eligió para el sacrificio, ordenó a Israel que fuera de ellas su alimento. Y así como Él, bendito sea, aleja a las aves impuras para el sacrificio, así las aleja para la alimentación de Israel; y todo esto para enseñarnos que Él, exaltado sea, odia la cualidad del mal y la crueldad, y ama la cualidad del bien, la humildad y la mansedumbre». Es decir, las aves prohibidas para comer son crueles, y cuando se come de ellas entra la cualidad de la crueldad en el cuerpo del que come. Por eso el Eterno, bendito sea, nos ordenó no comer aves impuras, para que no entrara en nuestra sangre la cualidad de la crueldad. Con esta prohibición nos enseña el Creador del mundo que «Él, exaltado sea, odia la cualidad del mal y la crueldad, y ama la cualidad del bien, la humildad y la mansedumbre»."})

BLOQUES.append({"t": "saludo",
  "he": "שַׁבָּת שָׁלוֹם וּמְבוֹרָךְ, חַג שָׂמֵחַ, חוֹרֶף בָּרִיא וּגְאוּלָּה בְּרַחֲמִים אכי\"ר.",
  "es": "Shabat shalom y bendecido, feliz fiesta, un invierno saludable y redención con misericordia, <i>amén, ken yehí ratzón</i>."})

